CREATE TABLE IF NOT EXISTS users(id VARCHAR(64) PRIMARY KEY,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,language VARCHAR(8) NOT NULL DEFAULT 'zh-CN',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS schema_migrations(version INT PRIMARY KEY,applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS jwt_token_revocations(jti VARCHAR(64) PRIMARY KEY,expires_at DATETIME NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS chat_model_configs(user_id VARCHAR(64) PRIMARY KEY,base_url VARCHAR(2048) NOT NULL,model_name VARCHAR(200) NOT NULL,encrypted_api_key TEXT NOT NULL,api_key_hint VARCHAR(32),timeout_seconds INT NOT NULL DEFAULT 60,thinking_enabled BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS embedding_model_configs(user_id VARCHAR(64) PRIMARY KEY,base_url VARCHAR(2048) NOT NULL,model_name VARCHAR(200) NOT NULL,encrypted_api_key TEXT NOT NULL,api_key_hint VARCHAR(32),timeout_seconds INT NOT NULL DEFAULT 60,default_top_k INT NOT NULL DEFAULT 6,embedding_dimension INT NOT NULL DEFAULT 1024,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rerank_model_configs(user_id VARCHAR(64) PRIMARY KEY,base_url VARCHAR(2048) NOT NULL,model_name VARCHAR(200) NOT NULL,encrypted_api_key TEXT NOT NULL,api_key_hint VARCHAR(32),timeout_seconds INT NOT NULL DEFAULT 60,top_n INT NOT NULL DEFAULT 3,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS agent_settings(user_id VARCHAR(64) PRIMARY KEY,rerank_enabled BOOLEAN NOT NULL DEFAULT FALSE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS resource_index(id VARCHAR(64) PRIMARY KEY,user_id VARCHAR(64) NOT NULL,dataset_id VARCHAR(64) NOT NULL,kind VARCHAR(16) NOT NULL,name VARCHAR(512) NOT NULL,job_id VARCHAR(64) NOT NULL DEFAULT '',updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX owner_kind(user_id,kind),INDEX dataset_owner(dataset_id,user_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS conversations(id VARCHAR(64) PRIMARY KEY,user_id VARCHAR(64) NOT NULL,dataset_id VARCHAR(64) NOT NULL,title VARCHAR(200) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX owner(user_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS conversation_messages(id BIGINT AUTO_INCREMENT PRIMARY KEY,conversation_id VARCHAR(64) NOT NULL,role VARCHAR(16) NOT NULL,content MEDIUMTEXT NOT NULL,citations_json JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX conversation(conversation_id)) ENGINE=InnoDB;
